exec("import json,subprocess,sys,tempfile,unittest\nfrom pathlib import Path\nROOT=Path(__file__).parents[1]\nSCRIPT=ROOT/'mcp'/'readonly_reference.py'\n\nclass ReadonlyReferenceTests(unittest.TestCase):\n def run_adapter(self,root,*args): return subprocess.run([sys.executable,str(SCRIPT),str(root),*args],capture_output=True,text=True)\n def write_entry(self,path,identifier='k-2026-0042',title='Found'):\n  path.write_text(('---|id: '+identifier+'|type: knowledge|title: '+title+'|created: 2026-01-01|---||# '+title+'|').replace('|',chr(10)),encoding='utf-8')\n def test_read_finds_exact_frontmatter_id(self):\n  with tempfile.TemporaryDirectory() as tmp:\n   root=Path(tmp); self.write_entry(root/'knowledge.md'); result=self.run_adapter(root,'read','k-2026-0042')\n   self.assertEqual(result.returncode,0,result.stderr); self.assertIn('title: Found',result.stdout)\n def test_read_rejects_body_only_id(self):\n  with tempfile.TemporaryDirectory() as tmp:\n   root=Path(tmp); (root/'body.md').write_text('Body id: k-2026-0042',encoding='utf-8'); result=self.run_adapter(root,'read','k-2026-0042')\n   self.assertEqual(result.returncode,1); self.assertIn('Not found',result.stderr)\n def test_read_rejects_duplicate_id(self):\n  with tempfile.TemporaryDirectory() as tmp:\n   root=Path(tmp); self.write_entry(root/'a.md'); self.write_entry(root/'b.md'); result=self.run_adapter(root,'read','k-2026-0042')\n   self.assertEqual(result.returncode,2); self.assertIn('Ambiguous ID',result.stderr)\n def test_search_returns_structured_metadata(self):\n  with tempfile.TemporaryDirectory() as tmp:\n   root=Path(tmp); self.write_entry(root/'knowledge.md'); result=self.run_adapter(root,'search','found'); payload=json.loads(result.stdout)\n   self.assertEqual(result.returncode,0,result.stderr); self.assertEqual(payload[0]['path'],'knowledge.md'); self.assertEqual(payload[0]['id'],'k-2026-0042'); self.assertEqual(payload[0]['title'],'Found')\n def test_search_does_not_follow_external_symlink(self):\n  with tempfile.TemporaryDirectory() as tmp:\n   base=Path(tmp); root=base/'vault'; root.mkdir(); outside=base/'outside.md'; self.write_entry(outside,title='Outside')\n   try: (root/'link.md').symlink_to(outside)\n   except OSError: self.skipTest('symlinks unavailable')\n   result=self.run_adapter(root,'search','Outside'); self.assertEqual(result.returncode,0,result.stderr); self.assertEqual(json.loads(result.stdout),[])\n\nif __name__=='__main__': unittest.main()")
